long long solve(long long x, const vector<long long>& p10) {
    // 枚举可能的数位长度 d
    for (int d = 1; d <= 18; d++) {
        if (x % d != 0) continue;
        long long n = x / d;
        if (n >= 1 && n <= 1000000000000000000LL && check(n, d, p10)) {
            return n;
        }
